def _normalize_origin(origin: str) -> str:
    return origin.strip()


def _origin_allowed(origin: Optional[str]) -> Optional[str]:
    if not origin:
        return None
    o = _normalize_origin(origin)
    if not o:
        return None
    if ALLOWED_ORIGINS == ["*"]:
        return o
    for allowed in ALLOWED_ORIGINS:
        if _normalize_origin(allowed) == o:
            return o
    return None


def _cors_headers(origin: Optional[str], request_headers: Optional[str] = None) -> Dict[str, str]:
    hdrs: Dict[str, str] = {}
    if not origin:
        return hdrs
    allow_origin = _origin_allowed(origin)
    if not allow_origin:
        return hdrs
    hdrs["Access-Control-Allow-Origin"] = allow_origin if ALLOWED_ORIGINS != ["*"] else "*"
    hdrs["Vary"] = "Origin"
    hdrs["Access-Control-Allow-Methods"] = CORS_ALLOWED_METHODS
    allowed_headers = [h.strip() for h in CORS_ALLOWED_HEADERS if h.strip()]
    allowed_map = {h.lower(): h for h in allowed_headers}
    if request_headers:
        req = [h.strip() for h in request_headers.split(",") if h.strip()]
        safe: List[str] = []
        for h in req:
            canon = allowed_map.get(h.lower())
            if canon:
                safe.append(canon)
        if safe:
            uniq = []
            seen = set()
            for h in safe:
                k = h.lower()
                if k not in seen:
                    seen.add(k)
                    uniq.append(h)
            hdrs["Access-Control-Allow-Headers"] = ", ".join(uniq)
        else:
            hdrs["Access-Control-Allow-Headers"] = ", ".join(sorted(set(allowed_headers), key=str.lower))
    else:
        hdrs["Access-Control-Allow-Headers"] = ", ".join(sorted(set(allowed_headers), key=str.lower))
    if CORS_ALLOW_CREDENTIALS and ALLOWED_ORIGINS != ["*"]:
        hdrs["Access-Control-Allow-Credentials"] = "true"
    return hdrs


def _read_body(handler: BaseHTTPRequestHandler) -> bytes:
    te = handler.headers.get("Transfer-Encoding")
    if te and str(te).strip().lower() != "identity":
        raise ValueError("unsupported transfer-encoding")
    cl = handler.headers.get("Content-Length")
    if cl is None:
        raise ValueError("missing content-length")
    try:
        n = int(str(cl).strip())
    except Exception:
        raise ValueError("invalid content-length")
    if n < 0:
        raise ValueError("invalid content-length")
    if n > MAX_REQUEST_BYTES:
        raise ValueError("request too large")
    body = handler.rfile.read(n)
    if body is None:
        return b""
    if len(body) != n:
        raise ValueError("incomplete request body")
    return body


def _send_headers(handler: BaseHTTPRequestHandler, origin: Optional[str]) -> None:
    cors = _cors_headers(origin, handler.headers.get("Access-Control-Request-Headers"))
    for k, v in cors.items():
        handler.send_header(k, v)


def _http_error_json(handler: BaseHTTPRequestHandler, status: int, code: str, detail: Any, origin: Optional[str]) -> None:
    payload = {"error": code, "detail": detail}
    body = _json_dumps(payload)
    handler.send_response(status)
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Content-Length", str(len(body)))
    handler.send_header("Connection", "close")
    _send_headers(handler, origin)
    handler.end_headers()
    try:
        handler.wfile.write(body)
    except Exception:
        pass


