def _http_file(handler: BaseHTTPRequestHandler, path: str, content_type: str, origin: Optional[str]) -> None:
    try:
        st = os.stat(path)
        size = int(st.st_size)
    except Exception:
        handler.send_response(404)
        handler.send_header("Connection", "close")
        handler.send_header("Content-Length", "0")
        _send_headers(handler, origin)
        handler.end_headers()
        return
    handler.send_response(200)
    handler.send_header("Content-Type", content_type)
    handler.send_header("Content-Length", str(size))
    handler.send_header("Connection", "close")
    _send_headers(handler, origin)
    handler.end_headers()
    try:
        with open(path, "rb") as f:
            while True:
                chunk = f.read(64 * 1024)
                if not chunk:
                    break
                handler.wfile.write(chunk)
    except Exception:
        pass


def _send_sse_event(handler: BaseHTTPRequestHandler, data: str) -> None:
    if not data:
        return
    lines = data.replace("\r", "").split("\n")
    out = "".join(("data: " + line + "\n") for line in lines) + "\n"
    handler.wfile.write(out.encode("utf-8", errors="ignore"))
    handler.wfile.flush()


def _send_sse_comment(handler: BaseHTTPRequestHandler, text: str) -> None:
    out = (": " + text.replace("\r", "").replace("\n", " ") + "\n\n").encode("utf-8", errors="ignore")
    handler.wfile.write(out)
    handler.wfile.flush()


def _parse_retry_after(headers: Dict[str, str]) -> Optional[float]:
    ra = headers.get("retry-after") or headers.get("Retry-After") or headers.get("RETRY-AFTER")
    if not ra:
        return None
    s = str(ra).strip()
    if not s:
        return None
    try:
        v = float(s)
        if v >= 0:
            return v
    except Exception:
        pass
    try:
        dt = email.utils.parsedate_to_datetime(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        delta = (dt - datetime.datetime.now(datetime.timezone.utc)).total_seconds()
        return max(0.0, float(delta))
    except Exception:
        return None


def _load_api_keys(prefix: str, single_name: str) -> List[str]:
    keys: List[str] = []
    packed = os.environ.get(prefix)
    if packed:
        keys.extend([k.strip() for k in packed.split(",") if k.strip()])
    for i in range(1, 101):
        k = os.environ.get(f"{single_name}_{i}")
        if k and str(k).strip():
            keys.append(str(k).strip())
    single = os.environ.get(single_name)
    if single and str(single).strip():
        keys.append(str(single).strip())
    seen = set()
    out: List[str] = []
    for k in keys:
        if k not in seen:
            seen.add(k)
            out.append(k)
    return out


class ApiKeyPool:
    def __init__(self, api_keys: List[str]) -> None:
        if not api_keys:
            raise RuntimeError("No API keys found in environment")
        self._lock = threading.Lock()
        self._keys = list(api_keys)
        self._cooldown_until: Dict[str, float] = {k: 0.0 for k in self._keys}
        self._exhausted_until: Dict[str, float] = {k: 0.0 for k in self._keys}
        self._disabled: Dict[str, bool] = {k: False for k in self._keys}
        self._rr = 0

    def acquire(self) -> str:
        with self._lock:
            n = len(self._keys)
            now = _now()
            for _ in range(n):
                idx = self._rr % n
                self._rr += 1
                k = self._keys[idx]
                if self._disabled.get(k, False):
                    continue
                if now < self._cooldown_until.get(k, 0.0):
                    continue
                if now < self._exhausted_until.get(k, 0.0):
                    continue
                return k
            earliest: Optional[float] = None
            for k in self._keys:
                if self._disabled.get(k, False):
                    continue
                t = max(self._cooldown_until.get(k, 0.0), self._exhausted_until.get(k, 0.0))
                if earliest is None or t < earliest:
                    earliest = t
            if earliest is None:
                raise RuntimeError("All API keys are disabled")
            wait = max(0.0, earliest - now)
            raise RuntimeError(f"No available API keys (cooldown), retry after {wait:.2f}s")

    def mark_rate_limited(self, api_key: str, seconds: Optional[float]) -> None:
        backoff = float(seconds) if seconds is not None and seconds > 0 else 5.0
        until = _now() + backoff
        with self._lock:
            cur = self._cooldown_until.get(api_key, 0.0)
            if until > cur:
                self._cooldown_until[api_key] = until

    def mark_exhausted(self, api_key: str, seconds: Optional[float]) -> None:
        backoff = float(seconds) if seconds is not None and seconds > 0 else 86400.0
        until = _now() + backoff
        with self._lock:
            cur = self._exhausted_until.get(api_key, 0.0)
            if until > cur:
                self._exhausted_until[api_key] = until

    def disable(self, api_key: str) -> None:
        with self._lock:
            self._disabled[api_key] = True

    def stats(self) -> Dict[str, Any]:
        with self._lock:
            now = _now()
            total = len(self._keys)
            disabled = sum(1 for k in self._keys if self._disabled.get(k, False))
            available = 0
            for k in self._keys:
                if self._disabled.get(k, False):
                    continue
                if now < self._cooldown_until.get(k, 0.0):
                    continue
                if now < self._exhausted_until.get(k, 0.0):
                    continue
                available += 1
            return {"total": total, "available": available, "disabled": disabled}


