def _is_failover_status(status: int) -> bool:
    return status in (401, 403, 402, 429) or status >= 500


def _read_error_body(resp: http.client.HTTPResponse, limit: int = 65536) -> str:
    try:
        data = resp.read(limit + 1)
    except Exception:
        return ""
    if not data:
        return ""
    if len(data) > limit:
        data = data[:limit]
    try:
        return data.decode("utf-8", errors="replace")
    except Exception:
        return ""


def _extract_stream_delta(data_obj: Any) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    if not isinstance(data_obj, dict):
        return None, None, None
    choices = data_obj.get("choices")
    if not isinstance(choices, list) or not choices:
        return None, None, None
    c0 = choices[0]
    if not isinstance(c0, dict):
        return None, None, None
    delta = c0.get("delta")
    if isinstance(delta, dict):
        content = delta.get("content")
        reasoning = delta.get("reasoning_content")
        finish = c0.get("finish_reason")
        if isinstance(content, str) and content:
            return content, None, finish if isinstance(finish, str) and finish else None
        if isinstance(reasoning, str) and reasoning:
            return None, reasoning, finish if isinstance(finish, str) and finish else None
        if isinstance(finish, str) and finish:
            return None, None, finish
        return None, None, None
    msg = c0.get("message")
    if isinstance(msg, dict):
        content = msg.get("content")
        reasoning = msg.get("reasoning_content")
        finish = c0.get("finish_reason")
        if isinstance(content, str) and content:
            return content, None, finish if isinstance(finish, str) and finish else None
        if isinstance(reasoning, str) and reasoning:
            return None, reasoning, finish if isinstance(finish, str) and finish else None
    finish = c0.get("finish_reason")
    if isinstance(finish, str) and finish:
