def _parse_strict_json(s: str) -> Any:
    s = s.strip()
    if not s:
        raise ValueError("empty")
    decoder = json.JSONDecoder()
    start = 0
    while True:
        idx = s.find("{", start)
        if idx == -1:
            break
        try:
            obj, end = decoder.raw_decode(s[idx:])
            if end > 0:
                return obj
        except Exception:
            start = idx + 1
            continue
        start = idx + 1
    raise ValueError("no_json")


def _default_plan(query: str) -> Dict[str, Any]:
    return {"intent": "simple", "search_type": "auto", "category": None, "queries": [query], "memory_queries": [], "need_iterations": False}


def _plan_search_optional(query: str) -> Dict[str, Any]:
    if not PLANNER_ENABLE:
        return _default_plan(query)
    if _zai_api_key_optional() is None:
        return _default_plan(query)
    try:
        raw = _zai_json_completion(_planner_prompt(query), PLANNER_TIMEOUT)
        obj = _parse_strict_json(raw)
        if not isinstance(obj, dict):
            return _default_plan(query)
        intent = obj.get("intent")
        if intent not in ("simple", "complex"):
            intent = "complex" if bool(obj.get("need_iterations")) else "simple"
        search_type = obj.get("search_type")
        if search_type not in ("auto", "fast", "neural", "deep"):
            search_type = "deep" if intent == "complex" else "auto"
        category = obj.get("category")
        if category is not None and not isinstance(category, str):
            category = None
        queries = obj.get("queries")
        if not isinstance(queries, list) or not queries:
            queries = [query]
        queries2: List[str] = []
        for q in queries:
            if isinstance(q, str):
                t = q.strip()
                if t:
                    queries2.append(t)
        if not queries2:
            queries2 = [query]
        queries2 = queries2[:6]
        memory_queries = obj.get("memory_queries")
        mq: List[str] = []
        if isinstance(memory_queries, list):
            for q in memory_queries[:3]:
                if isinstance(q, str) and q.strip():
                    mq.append(q.strip())
        need_iterations_raw = obj.get("need_iterations")
        need_iterations = bool(need_iterations_raw) if isinstance(need_iterations_raw, (bool, int)) else (intent == "complex")
        return {"intent": intent, "search_type": search_type, "category": category, "queries": queries2, "memory_queries": mq, "need_iterations": need_iterations}
    except Exception:
        return _default_plan(query)


def _followup_plan_optional(original_query: str, current_queries: List[str], docs: List[Dict[str, Any]]) -> Dict[str, Any]:
    if not PLANNER_ENABLE:
        return {"need_more": False, "next_queries": [], "stop_reason": "planner_disabled"}
    if _zai_api_key_optional() is None:
        return {"need_more": False, "next_queries": [], "stop_reason": "planner_no_key"}
    try:
        raw = _zai_json_completion(_planner_followup_prompt(original_query, current_queries, docs), PLANNER_TIMEOUT)
        obj = _parse_strict_json(raw)
        if not isinstance(obj, dict):
            return {"need_more": False, "next_queries": [], "stop_reason": "invalid_planner"}
        need_more = bool(obj.get("need_more"))
        next_queries_raw = obj.get("next_queries")
        next_queries: List[str] = []
        if isinstance(next_queries_raw, list):
            for q in next_queries_raw[:5]:
                if isinstance(q, str) and q.strip():
                    next_queries.append(q.strip())
        stop_reason = obj.get("stop_reason")
        if not isinstance(stop_reason, str):
            stop_reason = ""
        return {"need_more": need_more, "next_queries": next_queries, "stop_reason": stop_reason}
    except Exception:
        return {"need_more": False, "next_queries": [], "stop_reason": "invalid_planner"}


def _parse_iso_date_to_ts(s: Any) -> Optional[float]:
    if not isinstance(s, str) or not s:
        return None
    t = s.strip()
    if not t:
        return None
    try:
        dt = datetime.datetime.fromisoformat(t.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.timestamp()
    except Exception:
        pass
    try:
        if len(t) >= 10:
            d = datetime.date.fromisoformat(t[:10])
            dt2 = datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
            return dt2.timestamp()
    except Exception:
        return None
    return None


def _sort_and_truncate_docs(docs: Dict[str, Dict[str, Any]], max_docs: int) -> List[Dict[str, Any]]:
    lst = list(docs.values())

    def key_fn(d: Dict[str, Any]) -> Tuple[int, float, float, str]:
        ts = _parse_iso_date_to_ts(d.get("publishedDate"))
        has_ts = 1 if ts is not None else 0
        score = d.get("score")
        sc = float(score) if isinstance(score, (int, float)) else 0.0
        title = d.get("title")
        tt = title if isinstance(title, str) else ""
        return (has_ts, ts or 0.0, sc, tt)

    lst.sort(key=key_fn, reverse=True)
    return lst[:max(1, int(max_docs))]


