def _build_web_context(docs: List[Dict[str, Any]], max_snippet_chars: int) -> str:
    parts: List[str] = []
    for i, d in enumerate(docs, start=1):
        url = d.get("url")
        title = d.get("title")
        if not isinstance(url, str) or not url:
            continue
        if not isinstance(title, str) or not title.strip():
            title = url
        pub = d.get("publishedDate")
        pub_s = pub if isinstance(pub, str) else ""
        summary = d.get("summary")
        highlights = d.get("highlights")
        text = d.get("text")
        snippet = ""
        if isinstance(highlights, list) and highlights:
            hs: List[str] = []
            for h in highlights[:6]:
                if isinstance(h, str) and h.strip():
                    hs.append(h.strip())
            if hs:
                snippet = "\n".join(hs)
        if not snippet and isinstance(summary, str) and summary.strip():
