        block = {"source_id": i, "title": title, "url": url, "publishedDate": pub_s, "snippet": snippet}
        parts.append(json.dumps(block, ensure_ascii=False))
    return "\n".join(parts)


def _build_memory_context(mem: Optional[Dict[str, Any]]) -> str:
    if not mem or not isinstance(mem, dict):
