            "title": title if isinstance(title, str) else "",
            "similarity": float(sim) if isinstance(sim, (int, float)) else None,
            "memory": memory.strip()
        }
        items.append(json.dumps(obj, ensure_ascii=False))
    return "\n".join(items)


