cerebras_pool: Optional[ApiKeyPool] = ApiKeyPool(CEREBRAS_KEYS) if CEREBRAS_KEYS else None


def _http_post_json(host: str, path: str, headers: Dict[str, str], payload: Any, timeout: float) -> Tuple[int, Dict[str, str], bytes]:
    body = _json_dumps(payload)
    conn = http.client.HTTPSConnection(host, timeout=timeout)
    try:
        conn.request("POST", path, body=body, headers=headers)
        resp = conn.getresponse()
        try:
            status = int(resp.status)
            resp_headers_list = resp.getheaders()
            resp_headers: Dict[str, str] = {}
            for k, v in resp_headers_list:
                if k:
                    resp_headers[str(k)] = str(v) if v is not None else ""
            data = resp.read()
            return status, resp_headers, data or b""
        finally:
            try:
                resp.close()
            except Exception:
                pass
    finally:
        try:
            conn.close()
        except Exception:
            pass


class ExaClient:
    def __init__(self, api_key: str) -> None:
        if not api_key:
            raise RuntimeError("Missing EXA_API_KEY")
        self._api_key = api_key

    def search_and_contents(self, query: str, search_type: str, category: Optional[str], num_results: int, additional_queries: Optional[List[str]], summary_query: str) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "query": query,
            "type": search_type,
            "numResults": max(1, min(100, int(num_results))),
            "contents": {
                "text": {"maxCharacters": EXA_TEXT_MAX_CHARS, "includeHtmlTags": False},
                "highlights": {"numSentences": EXA_HIGHLIGHTS_SENTENCES, "highlightsPerUrl": EXA_HIGHLIGHTS_PER_URL, "query": summary_query},
                "summary": {"query": summary_query},
                "extras": {"links": EXA_EXTRA_LINKS, "imageLinks": 0},
            },
        }
        if category:
            payload["category"] = category
        if additional_queries:
            payload["additionalQueries"] = additional_queries[:50]
        if EXA_ENABLE_CONTEXT:
            payload["context"] = True
        headers = {
            "x-api-key": self._api_key,
            "Content-Type": "application/json",
            "Accept": "application/json",
