def _is_failover_status(status: int) -> bool:
    return status in (401, 403, 402, 429) or status >= 500


def _read_error_body(resp: http.client.HTTPResponse, limit: int = 65536) -> str:
    try:
        data = resp.read(limit + 1)
    except Exception:
        return ""
    if not data:
        return ""
    if len(data) > limit:
        data = data[:limit]
    try:
        return data.decode("utf-8", errors="replace")
    except Exception:
        return ""


def _extract_stream_delta(data_obj: Any) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    if not isinstance(data_obj, dict):
        return None, None, None
    choices = data_obj.get("choices")
    if not isinstance(choices, list) or not choices:
        return None, None, None
    c0 = choices[0]
    if not isinstance(c0, dict):
        return None, None, None
    delta = c0.get("delta")
    if isinstance(delta, dict):
        content = delta.get("content")
        reasoning = delta.get("reasoning_content")
        finish = c0.get("finish_reason")
        if isinstance(content, str) and content:
            return content, None, finish if isinstance(finish, str) and finish else None
        if isinstance(reasoning, str) and reasoning:
            return None, reasoning, finish if isinstance(finish, str) and finish else None
        if isinstance(finish, str) and finish:
            return None, None, finish
        return None, None, None
    msg = c0.get("message")
    if isinstance(msg, dict):
        content = msg.get("content")
        reasoning = msg.get("reasoning_content")
        finish = c0.get("finish_reason")
        if isinstance(content, str) and content:
            return content, None, finish if isinstance(finish, str) and finish else None
        if isinstance(reasoning, str) and reasoning:
            return None, reasoning, finish if isinstance(finish, str) and finish else None
    finish = c0.get("finish_reason")
    if isinstance(finish, str) and finish:
        return None, None, finish
    return None, None, None


def _safe_user_tag(user: Optional[str]) -> str:
    if not user:
        return "user_default"
    s = str(user).strip()
    if not s:
        return "user_default"
    out: List[str] = []
    for ch in s:
        if ch.isalnum() or ch in ("-", "_", ":", ".", "@"):
            out.append(ch)
        else:
            out.append("_")
    tag = "".join(out)[:80]
    return tag or "user_default"


def _parse_mode(data: Dict[str, Any], messages: List[Dict[str, str]]) -> Tuple[str, bool, bool]:
    mode_raw = data.get("mode")
    research_flag = data.get("research")
    web_flag = data.get("web") if "web" in data else data.get("use_web")
    memory_flag = data.get("memory") if "memory" in data else data.get("use_memory")

    mode = ""
    if isinstance(mode_raw, str):
        mode = mode_raw.strip().lower()
    if isinstance(research_flag, bool) and research_flag:
        mode = "research"

    if messages and messages[-1].get("role") == "user":
        last = (messages[-1].get("content") or "").lstrip()
        low = last.lower()
        if last.startswith("/kutatas") or last.startswith("/research") or low.startswith("kutatás"):
            mode = "research"
        if last.startswith("/kereses") or last.startswith("/search"):
            mode = "search"
        if last.startswith("/chat"):
            mode = "chat"

    if mode in ("research", "kutatas", "deep", "deep_research"):
        final_mode = "research"
    elif mode in ("search", "kereses", "web", "browse"):
        final_mode = "search"
    elif mode in ("chat", "simple", "default", ""):
        final_mode = "chat"
    else:
        final_mode = "chat"

    enable_web = False
    enable_memory = False

    if final_mode in ("search", "research"):
        enable_web = True
        enable_memory = False

    if isinstance(web_flag, bool):
        enable_web = bool(web_flag)

    if isinstance(memory_flag, bool):
        enable_memory = bool(memory_flag)

    if final_mode == "chat":
        enable_web = False
        enable_memory = False

    if enable_memory and not SUPERMEMORY_ENABLE:
        enable_memory = False

    return final_mode, enable_web, enable_memory


def _parse_chat_request(raw: bytes) -> Tuple[List[Dict[str, str]], Optional[str], str, bool, bool, Optional[str], Optional[str], Optional[Dict[str, Any]]]:
    if not raw:
        raise ValueError("empty body")
    if len(raw) > MAX_REQUEST_BYTES:
        raise ValueError("request too large")
    try:
        data = json.loads(raw.decode("utf-8"))
    except Exception:
        raise ValueError("invalid json")
    if not isinstance(data, dict):
        raise ValueError("invalid body")
    msgs = data.get("messages")
    user = data.get("user")
    if msgs is None or not isinstance(msgs, list):
        raise ValueError("messages must be a list")
    if len(msgs) > MAX_MESSAGES:
        raise ValueError("too many messages")
    out: List[Dict[str, str]] = []
    for m in msgs:
        if not isinstance(m, dict):
            raise ValueError("message must be an object")
        role = m.get("role")
        content = m.get("content")
        if role not in ("system", "user", "assistant"):
            raise ValueError("invalid role")
        if content is None:
            content = ""
        if not isinstance(content, str):
            raise ValueError("content must be a string")
        if len(content) > MAX_MESSAGE_CHARS:
            raise ValueError("message too large")
        out.append({"role": str(role), "content": content})
    final_mode, enable_web, enable_memory = _parse_mode(data, out)
    user_str: Optional[str] = None if user is None else str(user)
    category: Optional[str] = None
    if isinstance(data.get("category"), str) and data.get("category").strip():
        category = str(data.get("category")).strip()
    conversation_id: Optional[str] = None
    if isinstance(data.get("conversation_id"), str) and data.get("conversation_id").strip():
        conversation_id = str(data.get("conversation_id")).strip()
    filters: Optional[Dict[str, Any]] = None
    if isinstance(data.get("filters"), dict):
        filters = data.get("filters")
    return out, user_str, final_mode, enable_web, enable_memory, category, conversation_id, filters


def _last_user_query(messages: List[Dict[str, str]]) -> str:
