def _zai_json_completion(messages: List[Dict[str, str]], timeout: float) -> str:
    payload: Dict[str, Any] = {
        "model": ZAI_MODEL_ID,
        "messages": messages,
        "temperature": PLANNER_TEMPERATURE,
        "top_p": 0.95,
        "max_tokens": PLANNER_MAX_TOKENS,
    }
    api_key = _zai_api_key_required()
    st, _, data = _http_post_json(ZAI_API_HOST, ZAI_CHAT_PATH, {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "Accept": "application/json",
        "User-Agent": "zai-planner",
    }, payload, timeout)
    if st != 200:
        raise RuntimeError(f"planner_status_{st}")
    try:
        obj = json.loads(data.decode("utf-8"))
    except Exception:
        raise RuntimeError("planner_invalid_json")
    try:
        return str(obj["choices"][0]["message"]["content"])
    except Exception:
        raise RuntimeError("planner_missing_content")


def _parse_strict_json(s: str) -> Any:
    s = s.strip()
    if not s:
        raise ValueError("empty")
    decoder = json.JSONDecoder()
    start = 0
    while True:
        idx = s.find("{", start)
        if idx == -1:
            break
        try:
            obj, end = decoder.raw_decode(s[idx:])
            if end > 0:
                return obj
        except Exception:
            start = idx + 1
            continue
        start = idx + 1
    raise ValueError("no_json")


def _default_plan(query: str) -> Dict[str, Any]:
    return {"intent": "simple", "search_type": "auto", "category": None, "queries": [query], "memory_queries": [], "need_iterations": False}


def _plan_search_optional(query: str) -> Dict[str, Any]:
    if not PLANNER_ENABLE:
        return _default_plan(query)
    if _zai_api_key_optional() is None:
        return _default_plan(query)
    try:
        raw = _zai_json_completion(_planner_prompt(query), PLANNER_TIMEOUT)
        obj = _parse_strict_json(raw)
        if not isinstance(obj, dict):
            return _default_plan(query)
        intent = obj.get("intent")
        if intent not in ("simple", "complex"):
            intent = "complex" if bool(obj.get("need_iterations")) else "simple"
        search_type = obj.get("search_type")
        if search_type not in ("auto", "fast", "neural", "deep"):
            search_type = "deep" if intent == "complex" else "auto"
        category = obj.get("category")
        if category is not None and not isinstance(category, str):
            category = None
        queries = obj.get("queries")
        if not isinstance(queries, list) or not queries:
            queries = [query]
        queries2: List[str] = []
        for q in queries:
            if isinstance(q, str):
                t = q.strip()
                if t:
                    queries2.append(t)
        if not queries2:
            queries2 = [query]
        queries2 = queries2[:6]
        memory_queries = obj.get("memory_queries")
        mq: List[str] = []
        if isinstance(memory_queries, list):
            for q in memory_queries[:3]:
                if isinstance(q, str) and q.strip():
                    mq.append(q.strip())
        need_iterations_raw = obj.get("need_iterations")
        need_iterations = bool(need_iterations_raw) if isinstance(need_iterations_raw, (bool, int)) else (intent == "complex")
        return {"intent": intent, "search_type": search_type, "category": category, "queries": queries2, "memory_queries": mq, "need_iterations": need_iterations}
    except Exception:
        return _default_plan(query)


def _followup_plan_optional(original_query: str, current_queries: List[str], docs: List[Dict[str, Any]]) -> Dict[str, Any]:
    if not PLANNER_ENABLE:
        return {"need_more": False, "next_queries": [], "stop_reason": "planner_disabled"}
    if _zai_api_key_optional() is None:
        return {"need_more": False, "next_queries": [], "stop_reason": "planner_no_key"}
    try:
        raw = _zai_json_completion(_planner_followup_prompt(original_query, current_queries, docs), PLANNER_TIMEOUT)
        obj = _parse_strict_json(raw)
        if not isinstance(obj, dict):
            return {"need_more": False, "next_queries": [], "stop_reason": "invalid_planner"}
        need_more = bool(obj.get("need_more"))
        next_queries_raw = obj.get("next_queries")
        next_queries: List[str] = []
        if isinstance(next_queries_raw, list):
            for q in next_queries_raw[:5]:
                if isinstance(q, str) and q.strip():
                    next_queries.append(q.strip())
        stop_reason = obj.get("stop_reason")
        if not isinstance(stop_reason, str):
            stop_reason = ""
        return {"need_more": need_more, "next_queries": next_queries, "stop_reason": stop_reason}
    except Exception:
        return {"need_more": False, "next_queries": [], "stop_reason": "invalid_planner"}


def _parse_iso_date_to_ts(s: Any) -> Optional[float]:
    if not isinstance(s, str) or not s:
        return None
    t = s.strip()
    if not t:
        return None
    try:
        dt = datetime.datetime.fromisoformat(t.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.timestamp()
    except Exception:
        pass
    try:
        if len(t) >= 10:
            d = datetime.date.fromisoformat(t[:10])
            dt2 = datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
            return dt2.timestamp()
    except Exception:
        return None
    return None


def _sort_and_truncate_docs(docs: Dict[str, Dict[str, Any]], max_docs: int) -> List[Dict[str, Any]]:
    lst = list(docs.values())

    def key_fn(d: Dict[str, Any]) -> Tuple[int, float, float, str]:
        ts = _parse_iso_date_to_ts(d.get("publishedDate"))
        has_ts = 1 if ts is not None else 0
        score = d.get("score")
        sc = float(score) if isinstance(score, (int, float)) else 0.0
        title = d.get("title")
        tt = title if isinstance(title, str) else ""
        return (has_ts, ts or 0.0, sc, tt)

    lst.sort(key=key_fn, reverse=True)
    return lst[:max(1, int(max_docs))]


def _format_sources(docs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    sources: List[Dict[str, Any]] = []
    idx = 1
    for d in docs:
        url = d.get("url")
        if not isinstance(url, str) or not url:
            continue
        title = d.get("title")
        if not isinstance(title, str) or not title.strip():
            title = url
        published = d.get("publishedDate")
        pub = published if isinstance(published, str) else ""
        sources.append({"id": idx, "title": title, "url": url, "publishedDate": pub})
        idx += 1
        if idx > 200:
            break
    return sources


def _build_web_context(docs: List[Dict[str, Any]], max_snippet_chars: int) -> str:
    parts: List[str] = []
    total_chars = 0
    max_total_chars = 50000
    for i, d in enumerate(docs, start=1):
        url = d.get("url")
        title = d.get("title")
        if not isinstance(url, str) or not url:
            continue
        if not isinstance(title, str) or not title.strip():
            title = url
        pub = d.get("publishedDate")
        pub_s = pub if isinstance(pub, str) else ""
        summary = d.get("summary")
        highlights = d.get("highlights")
        text = d.get("text")
        snippet = ""
        if isinstance(highlights, list) and highlights:
            hs: List[str] = []
            for h in highlights[:6]:
                if isinstance(h, str) and h.strip():
                    hs.append(h.strip())
            if hs:
                snippet = "\n".join(hs)
        if not snippet and isinstance(summary, str) and summary.strip():
            snippet = summary.strip()
        if not snippet and isinstance(text, str) and text.strip():
            snippet = text.strip()[:max_snippet_chars]
        block = {"source_id": i, "title": title, "url": url, "publishedDate": pub_s, "snippet": snippet}
        block_json = json.dumps(block, ensure_ascii=False)
        if total_chars + len(block_json) > max_total_chars:
            break
        total_chars += len(block_json)
        parts.append(block_json)
    return "\n".join(parts)


def _build_memory_context(mem: Optional[Dict[str, Any]]) -> str:
    if not mem or not isinstance(mem, dict):
        return ""
    results = mem.get("results")
    if not isinstance(results, list) or not results:
        return ""
    items: List[str] = []
    for r in results[:SUPERMEMORY_MEMORY_LIMIT]:
        if not isinstance(r, dict):
            continue
        mid = r.get("id")
        memory = r.get("memory") or r.get("content") or r.get("text")
        title = r.get("title")
        sim = r.get("similarity")
        if not isinstance(memory, str) or not memory.strip():
            continue
        obj = {
            "id": mid if isinstance(mid, str) else "",
            "title": title if isinstance(title, str) else "",
            "similarity": float(sim) if isinstance(sim, (int, float)) else None,
            "memory": memory.strip()
        }
        items.append(json.dumps(obj, ensure_ascii=False))
    return "\n".join(items)


def _assemble_messages_for_answer(original_messages: List[Dict[str, str]], web_context: str, memory_context: str, sources: List[Dict[str, Any]]) -> List[Dict[str, str]]:
    sys_lines = [
        "Mindig magyarul válaszolj.",
        "Úgy viselkedsz, mint egy Perplexity-szerű webes válaszadó: rövid, pontos, forrásokkal alátámasztott válaszokat adj.",
        "Ha web_context van, hivatkozz [1], [2] stb. formában a source_id-kre.",
        "Ha memory_context van, használd fel a korábbi beszélgetések kontextusát.",
        "Formázz markdown-nal: használj címsorokat, felsorolásokat, code block-okat ahol releváns."
    ]
    sys_content = "\n".join(sys_lines)
    if web_context:
        sys_content += f"\n\n<web_sources>\n{web_context}\n</web_sources>"
    if memory_context:
        sys_content += f"\n\n<memories>\n{memory_context}\n</memories>"
    if sources:
        sources_json = json.dumps(sources, ensure_ascii=False, indent=2)
        sys_content += f"\n\n<available_sources>\n{sources_json}\n</available_sources>"
    messages = [{"role": "system", "content": sys_content}]
    messages.extend(original_messages)
    return messages


def _do_retrieval(query: str, plan: Dict[str, Any], exa_client: ExaClient, mode: str) -> List[Dict[str, Any]]:
    docs_map: Dict[str, Dict[str, Any]] = {}
    all_queries: List[str] = list(plan.get("queries", [query]))
    search_type = plan.get("search_type", "auto")
    category = plan.get("category")
    need_iterations = plan.get("need_iterations", False)
    cycles = RETRIEVAL_CYCLES_DEEP if need_iterations else RETRIEVAL_CYCLES_FAST
    start_time = _now()
    for cycle in range(cycles):
        if _now() - start_time > RETRIEVAL_OVERALL_TIMEOUT:
            break
        current_queries = all_queries[cycle * RETRIEVAL_PARALLELISM:(cycle + 1) * RETRIEVAL_PARALLELISM]
        if not current_queries:
            break
        with concurrent.futures.ThreadPoolExecutor(max_workers=RETRIEVAL_PARALLELISM) as executor:
            futures = {}
            for q in current_queries:
                future = executor.submit(_single_search, q, exa_client, search_type, category, query)
                futures[future] = q
            done, not_done = concurrent.futures.wait(futures.keys(), timeout=RETRIEVAL_OVERALL_TIMEOUT - (_now() - start_time), return_when=concurrent.futures.FIRST_EXCEPTION)
            for future in done:
                try:
                    result = future.result(timeout=1.0)
                    if result and isinstance(result, list):
                        for doc in result:
                            url = doc.get("url")
                            if isinstance(url, str) and url:
                                if url not in docs_map:
                                    docs_map[url] = doc
                except Exception as e:
                    _log(f"Search failed for '{futures[future]}': {e}")
            for future in not_done:
                future.cancel()
        if len(docs_map) >= RETRIEVAL_MIN_DOCS_BEFORE_STOP:
            if need_iterations and cycle < cycles - 1:
                current_docs = _sort_and_truncate_docs(docs_map, RETRIEVAL_MAX_DOCS)
                followup = _followup_plan_optional(query, all_queries[:len(current_queries) * (cycle + 1)], current_docs)
                if not followup.get("need_more"):
                    break
                next_queries = followup.get("next_queries", [])
                if next_queries:
                    all_queries.extend(next_queries)
            else:
                break
        if not need_iterations:
            break
    return _sort_and_truncate_docs(docs_map, RETRIEVAL_MAX_DOCS)


def _single_search(query: str, exa_client: ExaClient, search_type: str, category: Optional[str], summary_query: str) -> List[Dict[str, Any]]:
    try:
        result = exa_client.search_and_contents(query, search_type, category, EXA_NUM_RESULTS, None, summary_query)
        results = result.get("results", [])
        return results if isinstance(results, list) else []
    except Exception as e:
        _log(f"Single search error: {e}")
        return []


def _stream_completion_cerebras(messages: List[Dict[str, str]], handler: BaseHTTPRequestHandler, origin: Optional[str]) -> None:
    if cerebras_pool is None:
        raise RuntimeError("No Cerebras API keys configured")
    payload: Dict[str, Any] = {
        "model": CEREBRAS_MODEL_ID,
        "messages": messages,
        "temperature": TEMPERATURE,
        "top_p": TOP_P,
        "stream": True,
        "max_completion_tokens": MAX_COMPLETION_TOKENS,
    }
    api_key = cerebras_pool.acquire()
    status, resp_headers, resp, conn = _cerebras_stream_request(api_key, payload, UPSTREAM_STREAM_TIMEOUT)
    if status != 200:
        error_body = _read_error_body(resp, 4096)
        try:
            resp.close()
        except:
            pass
        try:
            conn.close()
        except:
            pass
        if status == 429:
            retry_after = _parse_retry_after(resp_headers)
            cerebras_pool.mark_rate_limited(api_key, retry_after)
        elif status in (401, 403):
            cerebras_pool.disable(api_key)
        raise RuntimeError(f"cerebras_error status={status} body={error_body}")
    handler.send_response(200)
    handler.send_header("Content-Type", "text/event-stream; charset=utf-8")
    handler.send_header("Cache-Control", "no-cache")
    handler.send_header("Connection", "keep-alive")
    _send_headers(handler, origin)
    handler.end_headers()
    try:
        for line in resp:
            if not line:
                continue
            try:
                line_str = line.decode("utf-8", errors="replace").strip()
            except:
                continue
            if not line_str or line_str.startswith(":"):
                continue
            if line_str.startswith("data: "):
                data_str = line_str[6:]
                if data_str == "[DONE]":
                    break
                try:
                    data_obj = json.loads(data_str)
                    content, reasoning, finish = _extract_stream_delta(data_obj)
                    if content:
                        chunk = {"content": content}
                        _send_sse_event(handler, json.dumps(chunk, ensure_ascii=False))
                    if reasoning and STREAM_REASONING:
                        chunk = {"reasoning": reasoning}
                        _send_sse_event(handler, json.dumps(chunk, ensure_ascii=False))
                    if finish:
                        break
                except json.JSONDecodeError:
                    continue
    except (BrokenPipeError, ConnectionResetError):
        pass
    except http.client.IncompleteRead:
        pass
    finally:
        try:
            resp.close()
        except:
            pass
        try:
            conn.close()
        except:
            pass
        try:
            _send_sse_event(handler, json.dumps({"done": True}, ensure_ascii=False))
        except:
            pass


class ChatHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    wbufsize = 8192

    def log_message(self, format: str, *args: Any) -> None:
        pass

    def do_OPTIONS(self) -> None:
        origin = self.headers.get("Origin")
        self.send_response(204)
        self.send_header("Content-Length", "0")
        _send_headers(self, origin)
        self.end_headers()

    def do_GET(self) -> None:
        origin = self.headers.get("Origin")
        if self.path == "/" or self.path == "/index.html":
            _http_file(self, STATIC_INDEX_PATH, "text/html; charset=utf-8", origin)
        elif self.path == "/health":
            _http_json(self, 200, {"status": "ok"}, origin)
        elif self.path == "/stats":
            stats = cerebras_pool.stats() if cerebras_pool else {"total": 0, "available": 0, "disabled": 0}
            _http_json(self, 200, stats, origin)
        else:
            _http_error_json(self, 404, "not_found", "Path not found", origin)

    def do_POST(self) -> None:
        origin = self.headers.get("Origin")
        if self.path == "/v1/chat/completions" or self.path == "/chat":
            self._handle_chat(origin)
        else:
            _http_error_json(self, 404, "not_found", "Path not found", origin)

    def _handle_chat(self, origin: Optional[str]) -> None:
        if API_AUTH_TOKEN:
            auth_header = self.headers.get("Authorization")
            if not auth_header or not auth_header.startswith("Bearer "):
                _http_error_json(self, 401, "unauthorized", "Missing or invalid authorization", origin)
                return
            token = auth_header[7:].strip()
            if token != API_AUTH_TOKEN:
                _http_error_json(self, 401, "unauthorized", "Invalid token", origin)
                return
        try:
            body = _read_body(self)
        except ValueError as e:
            _http_error_json(self, 400, "invalid_request", str(e), origin)
            return
        try:
            messages, user, mode, enable_web, enable_memory, category, conversation_id, filters = _parse_chat_request(body)
        except ValueError as e:
            _http_error_json(self, 400, "invalid_request", str(e), origin)
            return
        query = _last_user_query(messages)
        web_context = ""
        memory_context = ""
        sources: List[Dict[str, Any]] = []
        if enable_web:
            try:
                exa_client = ExaClient(_exa_api_key_required())
                plan = _plan_search_optional(query)
                docs = _do_retrieval(query, plan, exa_client, mode)
                sources = _format_sources(docs)
                web_context = _build_web_context(docs, EXA_TEXT_MAX_CHARS)
            except Exception as e:
                _log(f"Web retrieval error: {e}")
        if enable_memory:
            try:
                sm_client = SupermemoryClient(_supermemory_api_key_required())
                user_tag = _safe_user_tag(user)
                mem_result = sm_client.search_memories(query, SUPERMEMORY_MEMORY_LIMIT, [user_tag], None, SUPERMEMORY_INCLUDE_FORGOTTEN, "auto")
                if mem_result:
                    memory_context = _build_memory_context(mem_result)
            except Exception as e:
                _log(f"Memory retrieval error: {e}")
        final_messages = _assemble_messages_for_answer(messages, web_context, memory_context, sources)
        try:
            _stream_completion_cerebras(final_messages, self, origin)
        except Exception as e:
            _log(f"Streaming error: {e}")
            try:
                _http_error_json(self, 500, "internal_error", str(e), origin)
            except:
                pass


def main() -> None:
    server = ThreadingHTTPServer((HOST, PORT), ChatHandler)
    server.daemon_threads = True
    print(f"Server listening on {HOST}:{PORT}", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down...", flush=True)
        server.shutdown()
        server.server_close()


if __name__ == "__main__":
    main()
